import re


def title_of(html: str) -> str:
    """Return the text between the first <title> and </title> tags in html.

    The page is passed in already fetched; this function performs no I/O.
    Tag matching is case-insensitive. Returns an empty string when there
    is no <title> element or it is not closed.
    """
    pattern = re.compile(r"<title\b[^>]*>(.*?)</title\s*>", re.IGNORECASE | re.DOTALL)
    m = pattern.search(html)
    if m is None:
        return ""
    return str(m.group(1))


def test_title_of_simple() -> None:
    assert title_of("<html><head><title>Hello</title></head></html>") == "Hello"


def test_title_of_missing() -> None:
    assert title_of("<html><body>no title here</body></html>") == ""


def test_title_of_empty_input() -> None:
    assert title_of("") == ""


def test_title_of_uppercase_tags() -> None:
    assert title_of("<HTML><TITLE>Shout</TITLE></HTML>") == "Shout"


def test_title_of_unclosed() -> None:
    assert title_of("<title>Never closed") == ""


def test_title_of_uses_first_title() -> None:
    html = "<title>First</title><title>Second</title>"
    assert title_of(html) == "First"
